class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(n):
            """Return the square-free part of n"""
            result = 1
            d = 2
            while d * d <= n:
                count = 0
                while n % d == 0:
                    n //= d
                    count += 1
                if count % 2 == 1:
                    result *= d
                d += 1
            if n > 1:
                result *= n
            return result

        # Group numbers by their square-free part
        groups = {}

        for num in nums:
            square_free = get_square_free(num)
            if square_free not in groups:
                groups[square_free] = []
            groups[square_free].append(num)

        # Find maximum sum among all groups
        max_sum = 0
        for group in groups.values():
            group_sum = sum(group)
            max_sum = max(max_sum, group_sum)

        return max_sum

